/* eslint-disable @typescript-eslint/no-explicit-any */

import { Template } from '@accordproject/cicero-core';
import { TemplateMarkInterpreter } from './TemplateMarkInterpreter';
import { TemplateMarkTransformer } from '@accordproject/markdown-template';
import { transform } from '@accordproject/markdown-transform';
import { JavaScriptEvaluator } from './JavaScriptEvaluator';
import { TemplateLogicBundler, type CompilerResult } from './TemplateLogicBundler';

export type State = object;
export type Response = object;
export type Event = object;

export type TriggerResponse = {
    result: Response;
    state: State;
    events: Event[];
}

export type InitResponse = {
    state: State;
}

/**
 * A template archive processor: can draft content using the
 * templatemark for the archive and trigger the logic of the archive.
 *
 * ## Logic execution modes (follows PR #50 design)
 *
 * The processor dispatches on the `runtime` field declared in the template's
 * `package.json` under `accordproject.runtime`:
 *
 * - `"typescript"` — the archive ships raw `.ts` source files.  The processor
 *   JIT-compiles them to JavaScript on every call via `TemplateLogicBundler`
 *   (webpack over an in-memory filesystem).  Type-checking is skipped for
 *   speed; compilation errors are surfaced as runtime exceptions.
 *
 * - `"es6"` — the archive ships a pre-built `logic/logic.js`.  The processor
 *   reads and evaluates it directly, with no recompilation overhead.  Use
 *   `transpileLogicToJavaScript(outputDirectory)` to produce this artifact
 *   from a TypeScript archive.
 */
export class TemplateArchiveProcessor {
    template: Template;

    /**
     * Creates a template archive processor
     * @param {Template} template - the template to be used by the processor
     */
    constructor(template: Template) {
        this.template = template;
    }

    /**
     * Drafts a template by merging it with data
     * @param {any} data the data to merge with the template
     * @param {string} format the output format
     * @param {any} options merge options
     * @param {[string]} currentTime the current value for 'now'
     * @returns {Promise} the drafted content
     */
    async draft(data: any, format: string, options: any, currentTime?: string): Promise<any> {
        // Setup
        const metadata = this.template.getMetadata();
        const templateKind = metadata.getTemplateType() !== 0 ? 'clause' : 'contract';

        // Get the data
        const modelManager = this.template.getModelManager();
        const engine = new TemplateMarkInterpreter(modelManager, {});
        const templateMarkTransformer = new TemplateMarkTransformer();
        const templateMarkDom = templateMarkTransformer.fromMarkdownTemplate(
            { content: this.template.getTemplate() }, modelManager, templateKind, {options});
        const now = currentTime ? currentTime : new Date().toISOString();
        const ciceroMark = await engine.generate(templateMarkDom, data, { now });
        const result = transform(ciceroMark.toJSON(), 'ciceromark', ['ciceromark_unquoted', format], null, options);
        return result;
    }

    /**
     * Trigger the logic of a template
     * @param {object} data - the contract/clause data
     * @param {object} request - the request to send to the template logic
     * @param {object} state - the current state of the template
     * @param {[string]} currentTime - the current time, defaults to now
     * @param {[number]} utcOffset - the UTC offset, defaults to zero
     * @returns {Promise} the response and any events
     */
    async trigger(data: any, request: any, state?: any, currentTime?: string, utcOffset?: number): Promise<TriggerResponse> {
        const code = await this._getLogicCode();
        const evaluator = new JavaScriptEvaluator();
        const evalResponse = await evaluator.evalDangerously({
            templateLogic: true,
            verbose: false,
            functionName: 'trigger',
            code,
            argumentNames: ['data', 'request', 'state'],
            arguments: [data, request, state, currentTime, utcOffset],
        });
        if (evalResponse.result) {
            return evalResponse.result;
        }
        throw new Error('Trigger failed with message: ' + evalResponse.message);
    }

    /**
     * Init the logic of a template
     * @param {object} data - the contract/clause data
     * @param {[string]} currentTime - the current time, defaults to now
     * @param {[number]} utcOffset - the UTC offset, defaults to zero
     * @returns {Promise} the initial state
     */
    async init(data: any, currentTime?: string, utcOffset?: number): Promise<InitResponse> {
        const code = await this._getLogicCode();
        const evaluator = new JavaScriptEvaluator();
        const evalResponse = await evaluator.evalDangerously({
            templateLogic: true,
            verbose: false,
            functionName: 'init',
            code,
            argumentNames: ['data'],
            arguments: [data, currentTime, utcOffset],
        });
        if (evalResponse.result) {
            return evalResponse.result;
        }
        throw new Error('Init failed with message: ' + evalResponse.message);
    }

    /**
     * Transpile the TypeScript template logic to a pre-built JavaScript bundle
     * (static / offline compilation — Mode 1 from PR #50).
     *
     * If `outputDirectory` is provided the bundle is written to
     * `<outputDirectory>/logic/logic.js` and the template's `package.json` is
     * updated to `runtime: "es6"` so that subsequent calls to `trigger()` /
     * `init()` skip recompilation entirely.
     *
     * @param outputDirectory  optional directory to write the compiled artifact
     * @returns the compiler result containing the bundled code and any errors
     */
    async transpileLogicToJavaScript(outputDirectory?: string): Promise<CompilerResult> {
        const language = this.template.getLogicManager().getLanguage();
        if (language !== 'typescript') {
            throw new Error(
                `transpileLogicToJavaScript() requires a TypeScript archive ` +
                `(runtime: "typescript"), but this archive has runtime: "${language}".`
            );
        }
        return new TemplateLogicBundler(this.template).transpile({}, outputDirectory);
    }

    // ──────────────────────────────────────────────────────────────────────────
    // Private helpers
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Resolve the ready-to-eval JavaScript source for the template logic,
     * dispatching on the archive's declared runtime mode.
     */
    private async _getLogicCode(): Promise<string> {
        const logicManager = this.template.getLogicManager();
        const language = logicManager.getLanguage();

        switch (language) {
            case 'es6': {
                // Pre-bundled mode: read logic/logic.js directly from the archive.
                const scripts = logicManager
                    .getScriptManager()
                    .getScriptsForTarget('es6') as any[];

                if (!scripts || scripts.length === 0) {
                    throw new Error(
                        `No es6 logic found in template archive. ` +
                        `Run transpileLogicToJavaScript() to produce a pre-built bundle.`
                    );
                }
                // The entry point is logic/logic.js by AP convention.
                const entry =
                    scripts.find((s: any) =>
                        s.getIdentifier().replace(/\\/g, '/').endsWith('logic/logic.js')
                    ) ?? scripts[0];
                return entry.getContents() as string;
            }

            case 'typescript': {
                // JIT mode: webpack-transpile on demand (PR #50 experimental path).
                const result = await new TemplateLogicBundler(this.template).transpile();
                if (result.errors.length > 0) {
                    throw new Error(
                        `TypeScript JIT compilation failed:\n${result.errors.join('\n')}`
                    );
                }
                if (!result.code) {
                    throw new Error('TypeScript JIT compilation produced no output');
                }
                return result.code;
            }

            default:
                throw new Error(
                    `Unsupported template logic runtime: '${language}'. ` +
                    `Expected 'typescript' (JIT) or 'es6' (pre-bundled).`
                );
        }
    }
}
