/* eslint-disable @typescript-eslint/no-explicit-any */

import { transpileModule, ModuleKind, ScriptTarget } from 'typescript';
import webpack from 'webpack';
import { Volume, createFsFromVolume } from 'memfs';
import { Union } from 'unionfs';
import path from 'path';
import fs from 'fs';
import { Template } from '@accordproject/cicero-core';
import { SMART_LEGAL_CONTRACT_BASE64 } from './runtime/declarations';

// linkfs ships without TypeScript declarations.
// The package exports `link` (not `linkfs`) as its bundling function.
// @ts-expect-error -- no type declarations for linkfs
import { link as linkfs } from 'linkfs';

/** The Accord Project convention for the template logic entry point. */
const ENTRY_TS = 'logic/logic.ts';

/**
 * The result of a JIT compilation pass.
 * Mirrors the CompilerResult type introduced in PR #50.
 */
export type CompilerResult = {
    /** The bundled ESM source code, present on success. */
    code?: string;
    /** Non-empty on failure. */
    errors: string[];
};

/**
 * Options for the transpilation pass.
 * Mirrors TranspileOptions from PR #50.
 */
export type TranspileOptions = {
    /** Log the webpack stats to stdout after compilation. */
    verbose?: boolean;
};

/**
 * Bundles the TypeScript logic of an Accord Project template archive into a
 * single self-contained ESM module.
 *
 * ## Design (follows PR #50 of accordproject/template-engine)
 *
 * The two-step pipeline:
 *
 * 1. **ts.transpileModule()** — each `.ts` source file in the template's
 *    ScriptManager is syntax-transformed to JavaScript individually (no
 *    type-checking). The Accord Project runtime prelude (TemplateLogic base
 *    class, state interfaces, etc.) is decoded from `SMART_LEGAL_CONTRACT_BASE64`
 *    and prepended to the entry file so template logic can `extends TemplateLogic`
 *    without an explicit import.
 *
 * 2. **webpack over memfs** — the transpiled JS files are written into an
 *    in-memory filesystem (`memfs`). A `linkfs` overlay bridges the virtual
 *    `/node_modules` path to the real `node_modules` on disk, enabling template
 *    logic to import third-party packages (e.g. `dayjs`, `decimal.js`). The two
 *    filesystems are merged via `unionfs` before being handed to webpack as its
 *    `inputFileSystem`. Webpack produces an ESM bundle that is safe to evaluate
 *    via a `data:` URL dynamic import.
 *
 * ## Modes (from PR #50's dual-mode design)
 *
 * - **JIT** (`runtime: "typescript"`) — call `transpile()` on demand.
 * - **Static / offline** (`runtime: "es6"`) — call `transpile(options, outputDir)`
 *   to write `logic/logic.js` + updated `package.json` to disk. Subsequent runs
 *   read the pre-built JS directly without recompiling.
 */
export class TemplateLogicBundler {
    template: Template;

    constructor(template: Template) {
        this.template = template;
    }

    /**
     * Convenience wrapper: transpile and return the bundled code, throwing on
     * any error. Used by `TemplateArchiveProcessor` for JIT execution.
     */
    async bundle(options: TranspileOptions = {}): Promise<string> {
        const result = await this.transpile(options);
        if (result.errors.length > 0) {
            throw new Error(
                `TemplateLogicBundler: compilation failed\n${result.errors.join('\n')}`
            );
        }
        if (!result.code) {
            throw new Error('TemplateLogicBundler: webpack produced no output');
        }
        return result.code;
    }

    /**
     * Transpile the TypeScript template logic to a bundled ESM JavaScript module.
     *
     * This is the JIT compilation path from PR #50. Type-checking is NOT
     * performed — only syntax transformation via `ts.transpileModule()`.
     *
     * @param options  compilation options
     * @param outputDirectory  if provided, write the bundle to disk and flip
     *                         `package.json` to `runtime: "es6"` (offline mode)
     */
    async transpile(options: TranspileOptions = {}, outputDirectory?: string): Promise<CompilerResult> {
        const sources = this.collectSources();

        if (!sources.has(ENTRY_TS)) {
            return {
                errors: [
                    `Template logic entry point '${ENTRY_TS}' not found in archive. ` +
                    `Available .ts scripts: ${[...sources.keys()].join(', ') || '(none)'}`
                ]
            };
        }

        // ── Step 1: decode the AP runtime prelude and transpile to JS ──────────
        // The prelude defines TemplateLogic, IState, IRequest, etc. It is
        // prepended to logic.js in the virtual FS so template classes can
        // `extends TemplateLogic<...>` without an explicit import statement.
        const runtimeTs = Buffer.from(SMART_LEGAL_CONTRACT_BASE64, 'base64').toString();
        const runtimeJs = transpileModule(runtimeTs, {
            compilerOptions: { module: ModuleKind.ESNext, target: ScriptTarget.ES2022 }
        }).outputText;

        // ── Step 2: transpile each .ts source to .js and write into memfs ─────
        const vol = new Volume();

        for (const [relPath, src] of sources.entries()) {
            const jsPath = '/' + relPath.replace(/\.ts$/, '.js');

            let js = transpileModule(src, {
                compilerOptions: {
                    module: ModuleKind.ESNext,
                    target: ScriptTarget.ES2022,
                    esModuleInterop: true,
                }
            }).outputText;

            // Prepend runtime to the entry so TemplateLogic is in scope
            if (relPath === ENTRY_TS) {
                js = `${runtimeJs}\n${js}`;
            }

            vol.mkdirSync(path.posix.dirname(jsPath), { recursive: true });
            vol.writeFileSync(jsPath, js);
        }

        // ── Step 3: build the merged filesystem ────────────────────────────────
        // linkfs bridges /node_modules in the virtual FS to the real node_modules
        // directory so webpack can resolve third-party packages.
        const memfsInstance = createFsFromVolume(vol);
        // __dirname is the compiled dist/ directory; node_modules sits one level up
        const realNodeModules = path.resolve(__dirname, '..', 'node_modules');
        const lfs = linkfs(memfsInstance as any, [['/node_modules', realNodeModules]]);

        const inputFs = new Union();
        inputFs.use(lfs as any);

        // Separate output volume so we don't pollute the input memfs
        const outputVol = new Volume();
        const outputFs = createFsFromVolume(outputVol);

        // ── Step 4: run webpack over the virtual filesystem ────────────────────
        return new Promise((resolve) => {
            const compiler = webpack({
                mode: 'production',
                entry: '/logic/logic.js',
                output: {
                    path: '/dist',
                    filename: 'bundle.js',
                    library: { type: 'module' },
                    chunkFormat: 'module',
                },
                experiments: { outputModule: true },
                resolve: { extensions: ['.js'] },
                // Disable minification so the output remains readable and the
                // data-URI round-trip through btoa/atob doesn't hit size issues.
                optimization: { minimize: false },
                // Suppress the default Node.js target polyfills — template logic
                // runs directly in Node.js and doesn't need browser shims.
                target: 'node',
            });

            // Swap in the virtual filesystems
            (compiler as any).inputFileSystem = inputFs;
            (compiler as any).outputFileSystem = outputFs as any;

            compiler.run((err, stats) => {
                compiler.close(() => { /* noop */ });

                if (err) {
                    resolve({ errors: [err.message] });
                    return;
                }
                if (stats?.hasErrors()) {
                    const errs = stats.toJson({ errors: true }).errors
                        ?.map((e: any) => e.message) ?? ['webpack compilation error'];
                    resolve({ errors: errs });
                    return;
                }

                if (options.verbose && stats) {
                    console.log(stats.toString({ colors: false }));
                }

                const code = outputVol.readFileSync('/dist/bundle.js') as unknown as Buffer;
                const codeStr = code.toString('utf8');

                if (outputDirectory) {
                    this.writeToDisk(outputDirectory, codeStr);
                }

                resolve({ code: codeStr, errors: [] });
            });
        });
    }

    /**
     * Write the compiled bundle to disk and update the template's `package.json`
     * to declare `runtime: "es6"`, enabling the pre-bundled execution mode on
     * subsequent runs (no recompilation needed).
     */
    private writeToDisk(outputDirectory: string, code: string): void {
        const logicJsPath = path.join(outputDirectory, 'logic', 'logic.js');
        fs.mkdirSync(path.dirname(logicJsPath), { recursive: true });
        fs.writeFileSync(logicJsPath, code, 'utf8');

        const pkgPath = path.join(outputDirectory, 'package.json');
        if (fs.existsSync(pkgPath)) {
            const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
            if (pkg.accordproject) {
                pkg.accordproject.runtime = 'es6';
            }
            fs.writeFileSync(pkgPath, JSON.stringify(pkg, null, 2) + '\n', 'utf8');
        }
    }

    /**
     * Collect the template's `.ts` sources from the ScriptManager.
     * Excludes `.d.ts` declaration files and compiled `dist/` artefacts.
     * Keyed by normalised forward-slash path relative to the template root.
     */
    private collectSources(): Map<string, string> {
        const scripts = this.template
            .getLogicManager()
            .getScriptManager()
            .getScriptsForTarget('typescript');

        const map = new Map<string, string>();
        for (const s of scripts as any[]) {
            const id: string = s.getIdentifier();
            if (!id.endsWith('.ts') || id.endsWith('.d.ts')) continue;
            const norm = id.replace(/\\/g, '/');
            if (norm.split('/').includes('dist')) continue;
            map.set(norm, s.getContents());
        }
        return map;
    }
}
